const headers = $json.headers ?? {};
const body = $json.body ?? $json;
const secret = $env.KLINORBIS_N8N_SHARED_SECRET;
if (!secret) throw new Error('KLINORBIS_N8N_SHARED_SECRET tanımlı değil');
const eventId = String(headers['x-klinorbis-event-id'] ?? body.eventId ?? '');
const timestamp = String(headers['x-klinorbis-timestamp'] ?? '');
const supplied = String(headers['x-klinorbis-signature'] ?? '').replace(/^sha256=/, '').toLowerCase();
if (!eventId || !/^\d{13}$/.test(timestamp) || Math.abs(Date.now() - Number(timestamp)) > 300000) throw new Error('Olay kimliği veya replay penceresi geçersiz');
const raw = JSON.stringify(body);
const key = await crypto.subtle.importKey('raw', new TextEncoder().encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
const bytes = await crypto.subtle.sign('HMAC', key, new TextEncoder().encode(`${timestamp}.${eventId}.${raw}`));
const expected = [...new Uint8Array(bytes)].map((byte) => byte.toString(16).padStart(2, '0')).join('');
let diff = expected.length ^ supplied.length;
for (let index = 0; index < Math.max(expected.length, supplied.length); index++) diff |= (expected.charCodeAt(index) || 0) ^ (supplied.charCodeAt(index) || 0);
if (diff !== 0) throw new Error('KLINORBIS olay imzası doğrulanamadı');
return [{ json: { ...body, eventId } }];

const allowed = new Set(['workflow.started','workflow.step','workflow.completed','workflow.failed','human.approval.requested']);
const body = $json.body ?? $json;
if (!allowed.has(body.eventType)) throw new Error('Desteklenmeyen olay türü');
const forbidden = new Set(['name','fullname','patientname','patientalias','tckn','nationalid','phone','telephone','mobile','email','diagnosis','clinicaltext','medicaltext','transcript','address']);
const pii = /(?:\b[1-9]\d{10}\b)|(?:\b(?:\+?90\s?|0)?(?:5\d{2}|[2-4]\d{2})[\s().-]*\d{3}[\s.-]*\d{2}[\s.-]*\d{2}\b)|(?:\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b)/i;
function blocked(value, depth = 0) {
  if (depth > 12) return true;
  if (typeof value === 'string') return pii.test(value);
  if (Array.isArray(value)) return value.some((item) => blocked(item, depth + 1));
  if (!value || typeof value !== 'object') return false;
  return Object.entries(value).some(([key, nested]) => forbidden.has(key.toLowerCase().replace(/[^a-z0-9]/g, '')) || blocked(nested, depth + 1));
}
if (blocked(body)) throw new Error('Veri minimizasyonu ihlali');
return [{ json: { eventId: String(body.eventId), eventType: body.eventType, workflowRunId: String(body.workflowRunId), ticketReference: body.ticketReference ? String(body.ticketReference) : undefined, unitCode: body.unitCode ? String(body.unitCode) : 'HIL', status: body.status ? String(body.status) : 'received', message: body.message ? String(body.message).slice(0, 280) : 'n8n adımı tamamlandı' } }];

const secret = $env.KLINORBIS_N8N_SHARED_SECRET;
if (!secret) throw new Error('KLINORBIS_N8N_SHARED_SECRET tanımlı değil');
const eventId = String($json.eventId);
const timestamp = String(Date.now());
const body = JSON.stringify($json);
const key = await crypto.subtle.importKey('raw', new TextEncoder().encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
const signatureBytes = await crypto.subtle.sign('HMAC', key, new TextEncoder().encode(`${timestamp}.${eventId}.${body}`));
const signature = [...new Uint8Array(signatureBytes)].map((byte) => byte.toString(16).padStart(2, '0')).join('');
return [{ json: { body, eventId, timestamp, signature } }];

const secret = $env.KLINORBIS_N8N_SHARED_SECRET;
if (!secret) throw new Error('KLINORBIS_N8N_SHARED_SECRET tanımlı değil');
const eventId = `n8n-agent-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
const timestamp = String(Date.now());
const body = JSON.stringify({ action: 'tick' });
const key = await crypto.subtle.importKey('raw', new TextEncoder().encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
const bytes = await crypto.subtle.sign('HMAC', key, new TextEncoder().encode(`${timestamp}.${eventId}.${body}`));
const signature = [...new Uint8Array(bytes)].map((byte) => byte.toString(16).padStart(2, '0')).join('');
return [{ json: { body, eventId, timestamp, signature } }];
